-- Generated by Automations/create_tables.py; embedding column added for Automations/create_embeddings.py
CREATE EXTENSION IF NOT EXISTS vector;

DROP TABLE IF EXISTS bioprojects;

CREATE TABLE bioprojects (
    bioproject               TEXT NOT NULL,
    sra_study                TEXT NOT NULL,
    n_experiments            INTEGER,
    found_in_bioproject_xml  BOOLEAN,
    bioproject_uid           BIGINT,
    name                     TEXT,
    title                    TEXT,
    description              TEXT,
    data_types               TEXT,
    organism_name            TEXT,
    tax_id                   BIGINT,
    supergroup               TEXT,
    target_material          TEXT,
    target_capture           TEXT,
    sample_scope             TEXT,
    method_type              TEXT,
    objectives               TEXT,
    relevance                TEXT,
    project_release_date     DATE,
    geo_accessions           TEXT,
    center_ids               JSONB,
    external_links           JSONB,
    grants                   JSONB,
    publication_count        INTEGER,
    pubmed_ids               TEXT,
    first_publication_date   DATE,
    journals                 TEXT,
    publication_titles       TEXT,
    publications             JSONB,
    submission_id            TEXT,
    submitted_date           DATE,
    last_update_date         DATE,
    organization             TEXT,
    organization_country     TEXT,
    access                   TEXT,
    parent_projects          TEXT,
    embedding                vector(768),            -- BioBERT (name, title, description, organism_name), L2-normalised
    PRIMARY KEY (bioproject, sra_study)
);

\copy bioprojects FROM '/work/11795/dgrigor/ls6/projects/sra_explorer/Automations/output/bioprojects_embeddings.csv' WITH (FORMAT csv, HEADER true)

CREATE INDEX ON bioprojects (sra_study);
CREATE INDEX ON bioprojects (tax_id);

-- Approximate nearest-neighbour index for semantic search (cosine distance, operator <=>)
SET maintenance_work_mem = '4GB';
CREATE INDEX ON bioprojects USING hnsw (embedding vector_cosine_ops);
